            color = QColor(st.t.ok if copied else st.t.text if on else st.t.text_3)
            tw = st.m.text_w(label, f)
            st.m.draw_text(p, cr.x() + (COPY_W - tw) / 2, cr.y() + (COPY_H - st.m.line_h(f)) / 2, label, f, color)

