    MT = 26
    __slots__ = ("item", "sid", "cwd", "doc", "bubble", "thumbs", "chips", "attach_h", "queued", "busy", "_html")

    def __init__(self, item: UserItem, sid: str, cwd: str) -> None:
        super().__init__(f"user:{item.id}")
