            st.m.draw_text(p, cx + 10, y + (26 - st.m.line_h(f)) / 2, label, f, QColor(t.text))
            if args_w:
                st.m.draw_text(p, cx + lw + 8, y + (26 - st.m.line_h(f)) / 2, it.command.args, f, QColor(t.text_2))
