    def _place_jump(self) -> None:
        vp = self.view.viewport()
        self.jump.adjustSize()
        self.jump.move((vp.width() - self.jump.width()) // 2, vp.height() - 18 - self.jump.height())

    def _place_find(self) -> None:
        bar = self.find_bar
