        def ok(e: Json) -> None:
            self._show_box(None)
            store.toast(f"Registered {e.get('name')}", "success")
            row = self.rows.get(str(e.get("id")))
            if row is not None:
                row.set_open(True)

        store.call("repos.save", {"path": path}).then(ok).catch(lambda e: store.toast(err_text(e), "error"))

