    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        bd = getattr(self, "backdrop", None)
        if bd is not None:
            bd.paint(p, self)
        else:
            p.fillRect(self.rect(), theme.qcolor(theme.tokens().scrim))
