    def set(self, project: str, icon: str, ref: str) -> None:
        self._icon = icon
        self.project.set_full(project)
        self.project.setVisible(bool(project))
        self.project.setSizePolicy(QSizePolicy.Policy.Maximum, QSizePolicy.Policy.Fixed)
