    def _recents(self) -> List[str]:
        out: List[str] = []
        for p in (store.config or {}).get("recentProjects") or []:
            if p and str(p) not in out:
                out.append(str(p))
        for s in store.sessions:
            if len(out) >= 8:
                break
            p = str(s.get("project") or s.get("cwd") or "")
            if p and not s.get("archived") and p not in out:
                out.append(p)
        return out[:6]

