function loadNodePty() {
  if (nodePty !== undefined) return nodePty;
  try {
    nodePty = require('node-pty');
  } catch {
    nodePty = null;
  }
  return nodePty;
}

export function capabilities() {
  const python = IS_WIN ? null : which('python3') || which('python');
  const script = IS_WIN ? null : which('script');
