import { Fragment, memo, useEffect, useMemo, useState, type ReactNode } from 'react';
import { diffWordsWithSpace } from 'diff';
import { MessageSquarePlus, Trash, Check } from 'lucide-react';
import { highlightTokens, cachedTokens, PAINT_LINES, type Tok } from '../lib/highlight';
import { parseAnsi } from '../lib/ansi';
import { langFromPath, plural } from '../lib/format';
import type { DiffHunk, DiffLine } from '../lib/types';
import { stagger } from '../lib/motion';

type Range = [number, number];

function renderContent(text: string, toks?: Tok[] | null, ranges?: Range[] | null): ReactNode {
  if (!toks && !ranges?.length) return text || '\u200b';
  const segs = toks && toks.length ? toks : [{ t: text } as Tok];
  const rs = ranges || [];
  const out: ReactNode[] = [];
  let pos = 0;
  let ri = 0;
  let k = 0;
  for (const tok of segs) {
    const s = tok.t;
    let start = 0;
    while (start < s.length) {
      const abs = pos + start;
      while (ri < rs.length && rs[ri][1] <= abs) ri++;
      let end = s.length;
      let marked = false;
      if (ri < rs.length) {
        const [a, b] = rs[ri];
        if (abs >= a) {
          marked = true;
          end = Math.min(s.length, b - pos);
        } else end = Math.min(s.length, a - pos);
      }
      const piece = s.slice(start, end);
      const span = (
        <span key={k++} style={tok.s as React.CSSProperties}>
          {piece}
        </span>
      );
      out.push(marked ? <mark key={k++}>{span}</mark> : span);
      start = end;
    }
    pos += s.length;
  }
  return out.length ? out : '\u200b';
}

/** Token lines for a text, filled in once highlighting finishes (never, past MAX_HIGHLIGHT in lib/highlight). */
function useTokens(text: string, lang: string | null) {
  const [toks, setToks] = useState<Tok[][] | null>(() => cachedTokens(text, lang));
  useEffect(() => {
    let alive = true;
    const hit = cachedTokens(text, lang);
    if (hit) setToks(hit);
    else
      highlightTokens(text, lang, () => alive).then((t) => {
        if (alive) setToks(t);
      });
    return () => {
      alive = false;
    };
  }, [text, lang]);
  return toks;
}

// ---------------------------------------------------------------- CodeView

export const CodeView = memo(function CodeView({ text, path, lang, startLine = 1, maxLines = 400, wrap = false, highlightLine }: { text: string; path?: string; lang?: string; startLine?: number; maxLines?: number; wrap?: boolean; highlightLine?: number }) {
  const [all, setAll] = useState(false);
  const language = lang || (path ? langFromPath(path) : 'text');
  const lines = useMemo(() => {
    const l = text.split('\n');
    if (l.length > 1 && l[l.length - 1] === '') l.pop();
    return l;
  }, [text]);
  const shown = all ? lines : lines.slice(0, maxLines);
  const toks = useTokens(text, language);
  // Colour goes on PAINT_LINES lines per frame (as in Markdown's paintCode): all of a long file's at
  // once, after "Show all", was a 240 ms frame for 1,300 lines here. Coloured that way it arrives
  // gradually, so a long grid goes without the fade-in.
  const [painted, setPainted] = useState(PAINT_LINES);
  useEffect(() => {
    if (!toks || painted >= shown.length) return;
    const t = requestAnimationFrame(() => setPainted((p) => p + PAINT_LINES));
    return () => cancelAnimationFrame(t);
  }, [toks, painted, shown.length]);
  return (
    <div className={`code-view${wrap ? ' wrap' : ''}${lines.length > shown.length ? ' clipped' : ''}`}>
      <div className="code-grid" data-hl={toks ? (shown.length > PAINT_LINES ? 'sliced' : '1') : '0'}>
        {shown.map((l, i) => (
          <CodeLine key={i} n={startLine + i} text={l} toks={i < painted ? toks?.[i] : null} hit={highlightLine === startLine + i} />
        ))}
      </div>
      {lines.length > shown.length && (
        <button className="code-more fade" onClick={() => setAll(true)}>
          Show all {lines.length} lines
        </button>
      )}
    </div>
  );
});

/** One numbered line; unchanged lines are skipped while the colour spreads down the grid. */
const CodeLine = memo(function CodeLine({ n, text, toks, hit }: { n: number; text: string; toks?: Tok[] | null; hit: boolean }) {
  return (
    <>
      <span className={`ln${hit ? ' hit' : ''}`}>{n}</span>
      <span className={`hl-line${hit ? ' hit' : ''}`}>{renderContent(text, toks)}</span>
    </>
  );
});

// ---------------------------------------------------------------- Ansi

export const AnsiText = memo(function AnsiText({ text }: { text: string }) {
  const segs = useMemo(() => parseAnsi(text), [text]);
  return (
    <>
      {segs.map((s, i) =>
        s.cls || s.style ? (
          <span key={i} className={s.cls} style={s.style}>
            {s.text}
          </span>
        ) : (
          <Fragment key={i}>{s.text}</Fragment>
        ),
      )}
    </>
  );
});

// ---------------------------------------------------------------- DiffView

type Row = { kind: 'hunk'; hunk: DiffHunk; hi: number } | { kind: 'line'; line: DiffLine } | { kind: 'split'; left: DiffLine | null; right: DiffLine | null };

function wordRanges(hunks: DiffHunk[]) {
  const map = new WeakMap<DiffLine, Range[]>();
  for (const h of hunks) {
    const ls = h.lines;
    for (let i = 0; i < ls.length; ) {
      if (ls[i].t !== '-') {
        i++;
        continue;
      }
      const dels: DiffLine[] = [];
      while (i < ls.length && ls[i].t === '-') dels.push(ls[i++]);
      const adds: DiffLine[] = [];
      while (i < ls.length && ls[i].t === '+') adds.push(ls[i++]);
      const n = Math.min(dels.length, adds.length);
      for (let k = 0; k < n; k++) {
        const a = dels[k].s;
        const b = adds[k].s;
        if (a.length > 2000 || b.length > 2000) continue;
        const parts = diffWordsWithSpace(a, b);
        const rd: Range[] = [];
        const ra: Range[] = [];
        let pa = 0;
        let pb = 0;
        let changed = 0;
        for (const p of parts) {
          const len = p.value.length;
          if (p.removed) {
            rd.push([pa, pa + len]);
            pa += len;
            changed += len;
          } else if (p.added) {
            ra.push([pb, pb + len]);
            pb += len;
            changed += len;
          } else {
            pa += len;
            pb += len;
          }
        }
        if (changed < (a.length + b.length) * 0.7) {
          map.set(dels[k], rd);
          map.set(adds[k], ra);
        }
      }
    }
  }
  return map;
}

function useHunkTokens(hunks: DiffHunk[], lang: string) {
  const [state, setState] = useState<Map<DiffLine, Tok[]>>(new Map());
  useEffect(() => {
    let alive = true;
    (async () => {
      const map = new Map<DiffLine, Tok[]>();
      for (const h of hunks) {
        const oldL = h.lines.filter((l) => l.t !== '+');
        const newL = h.lines.filter((l) => l.t !== '-');
        const wanted = () => alive;
        const [ot, nt] = await Promise.all([highlightTokens(oldL.map((l) => l.s).join('\n'), lang, wanted), highlightTokens(newL.map((l) => l.s).join('\n'), lang, wanted)]);
        if (!ot && !nt) return;
        oldL.forEach((l, i) => ot?.[i] && map.set(l, ot[i]));
        newL.forEach((l, i) => nt?.[i] && map.set(l, nt[i]));
      }
      if (alive) setState(map);
    })();
    return () => {
      alive = false;
    };
  }, [hunks, lang]);
  return state;
}

const NO_ANIM: React.CSSProperties = { animation: 'none' };

export const DiffView = memo(function DiffView({
  hunks,
  path,
  mode = 'unified',
