      shownRef.current = cur;
      setShown(cur);
      raf.current = requestAnimationFrame(tick);
    };
    raf.current = requestAnimationFrame(tick);
  }, [text, live]);

  useEffect(
    () => () => {
      if (raf.current != null) cancelAnimationFrame(raf.current);
    },
    [],
  );

  return shown >= text.length ? text : text.slice(0, shown);
}

/** A value that updates at most every `ms`, so a fast-changing ticker reads as a glide, not a flicker. */
export function useThrottled<T>(value: T, ms: number): T {
  const [shown, setShown] = useState(value);
  const last = useRef(0);
  const timer = useRef<number | null>(null);
  const latest = useRef(value);
  latest.current = value;
  useEffect(() => {
    const due = last.current + ms - Date.now();
    if (due <= 0) {
      last.current = Date.now();
      setShown(value);
      return;
    }
    if (timer.current == null) {
      timer.current = window.setTimeout(() => {
        timer.current = null;
        last.current = Date.now();
        setShown(latest.current);
      }, due);
    }
  }, [value, ms]);
  return shown;
}

/**
 * Let the browser draw a frame and handle input before going on: long work done in slices awaits this
 * between them. A message, not a timer: nested timers are clamped to 4 ms.
 */
export function yieldToEvents() {
  return new Promise<void>((done) => {
    const ch = new MessageChannel();
    ch.port1.onmessage = () => done();
    ch.port2.postMessage(null);
  });
}
