  private onAssistant(m: RawMsg) {
    if (m.uuid) {
      if (this.seen.has(m.uuid)) return;
      this.seen.add(m.uuid);
    }
    const parent: string | null = m.parent_tool_use_id || null;
    const msg = messageOf(m);
