  background: var(--err-wash);
  font-size: var(--fs-small);
}
.render-fault-text {
  flex: 1;
  min-width: 0;
}
.render-fault-why {
  color: var(--text-3);
}
.render-fault-retry {
  display: inline-flex;
  align-items: center;
  gap: var(--sp-1);
  color: var(--text-2);
}
