  background: var(--text-4);
}
.dp-glyph.done {
  background: var(--ok);
}
.dp-glyph.running,
.dp-glyph.preparing {
  background: var(--accent);
}
.dp-glyph.needs_action {
  background: var(--warn);
}
.dp-glyph.failed {
  background: var(--err);
}
.dp-glyph.stopped {
  background: var(--text-3);
}
.dp-glyph.queued,
.dp-glyph.skipped {
