.sched {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: var(--sp-1_5);
  padding: var(--sp-2_5) var(--sp-2) var(--sp-3) var(--sp-3);
  border-radius: var(--r-5);
  background: var(--card);
  box-shadow: var(--card-shadow);
  overflow: hidden;
}
.sched:hover {
  box-shadow: var(--card-shadow-hover);
}
.sched.on {
  box-shadow: 0 0 0 1.5px var(--accent-line);
}
.sched.off .sched-name,
.sched.off .sched-sub {
  color: var(--text-3);
}
.sched-main {
  display: grid;
  gap: var(--sp-0_5);
  min-width: 0;
  text-align: left;
}
.sched-name {
  font-size: var(--fs-small);
  font-weight: 560;
}
.sched-sub {
  font-size: var(--fs-micro);
  color: var(--text-3);
}
.sched-next {
  display: block;
  font-size: var(--fs-micro);
  color: var(--text-2);
  margin-top: var(--sp-0_5);
