}
.cfile-toggle {
  flex: 1;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: var(--sp-1_75);
  height: 30px;
  padding: 0 var(--sp-1);
  text-align: left;
  border-radius: var(--r-2);
}
.cfile-toggle > svg {
