}
.fstat.s-R {
  color: var(--info);
  background: var(--info-wash);
}
.cfile-body .diff {
  border-radius: 0;
  max-height: none;
  box-shadow: none;
  background: var(--canvas);
}
.cfile-body .diff-grid {
  padding: var(--sp-1) 0 var(--sp-2);
}
.cfile-note {
  padding: var(--sp-3) var(--sp-3_5);
  font-size: var(--fs-small);
}
.notes-bar {
  flex: none;
  display: flex;
  align-items: center;
  gap: var(--sp-2);
  padding: var(--sp-2_5) var(--sp-3);
  background: var(--raised);
  box-shadow: inset 0 1px 0 var(--hair-2);
  color: var(--text);
  font-size: var(--fs-small);
}

/* ---------------------------------------------------------------- files */

.files {
  display: flex;
  flex-direction: column;
  min-height: 0;
}
.files-body {
  flex: 1;
  min-height: 0;
  display: flex;
}
.tree {
  width: 212px;
  flex: none;
