}
.crumb-chev {
  opacity: 0.7;
  margin-left: 1px;
}

/* folder picker (popover) */
.fpick {
  display: flex;
  flex-direction: column;
  min-height: 0;
  max-height: min(60vh, 460px);
}
.fpick-search {
  display: flex;
  align-items: center;
  gap: var(--sp-2);
  height: 36px;
  padding: 0 var(--sp-2_5) 0 var(--sp-3);
  border-bottom: 1px solid var(--hair);
  color: var(--text-3);
  cursor: text;
}
.fpick-search input {
